#!/usr/bin/env python3
"""Probe: render {name: body} through marmite, isolating rendered markdown body."""
import os, shutil, subprocess, sys, tempfile, json

BIN = "/tmp/orig/marmite_ref"

def render_bodies(bodies, binary=BIN, fm=True, extra=None, config=None, keep=None):
    """bodies: dict slug -> markdown body. Returns dict slug -> html (or None)."""
    work = keep or tempfile.mkdtemp(prefix="mdp-")
    if keep:
        shutil.rmtree(work, ignore_errors=True); os.makedirs(work)
    tdir = os.path.join(work, "templates"); os.makedirs(tdir, exist_ok=True)
    open(os.path.join(tdir, "content.html"), "w").write("{{ content.html }}")
    open(os.path.join(tdir, "list.html"), "w").write("")
    open(os.path.join(tdir, "group.html"), "w").write("")
    for slug, body in bodies.items():
        head = "---\ntitle: T\nslug: %s\n---\n" % slug if fm else ""
        with open(os.path.join(work, slug + ".md"), "w") as f:
            f.write(head + body)
    for rel, content in (extra or {}).items():
        p = os.path.join(work, rel)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        if isinstance(content, bytes): open(p, "wb").write(content)
        else: open(p, "w").write(content)
    if config: open(os.path.join(work, "marmite.yaml"), "w").write(config)
    site = os.path.join(work, "_site")
    p = subprocess.run([binary, work, site], capture_output=True, text=True)
    out = {}
    for slug in bodies:
        fp = os.path.join(site, slug + ".html")
        out[slug] = open(fp).read() if os.path.exists(fp) else None
    if not keep: shutil.rmtree(work, ignore_errors=True)
    return out, p

def show(bodies, **kw):
    out, p = render_bodies(bodies, **kw)
    for slug in bodies:
        print("=== %s" % slug)
        print("--- IN:"); print(bodies[slug], end="" if bodies[slug].endswith("\n") else "\n")
        print("--- OUT:")
        print(out[slug] if out[slug] is not None else "<<<MISSING>>>")
        print()
    if p.returncode != 0:
        print("RC=%s" % p.returncode); print(p.stdout[-3000:]); print(p.stderr[-3000:])
    return out
